# backend.tf - remote state for the prod data-lake stack
terraform {
  required_version = ">= 1.6"

  backend "s3" {
    bucket         = "acme-tf-state"
    key            = "data-lake/prod/terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = "acme-tf-locks" # holds the lock item during apply
    encrypt        = true            # encrypt state at rest with SSE
  }

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# The state bucket and lock table themselves are usually managed in a
# separate bootstrap stack (with local state, or created by hand once).
# bootstrap/main.tf
resource "aws_s3_bucket" "state" {
  bucket = "acme-tf-state"
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id
  versioning_configuration { status = "Enabled" } # enables state recovery
}

resource "aws_dynamodb_table" "locks" {
  name         = "acme-tf-locks"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID" # required key name for the S3 backend lock

  attribute {
    name = "LockID"
    type = "S"
  }
}

# modules/bucket/variables.tf
variable "name" {
  description = "Bucket name"
  type        = string
}

variable "retention_days" {
  description = "Days before non-current versions expire"
  type        = number
  default     = 90

  validation {
    condition     = var.retention_days > 0
    error_message = "retention_days must be positive."
  }
}

# modules/bucket/main.tf
resource "aws_s3_bucket" "this" {
  bucket = var.name
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    id     = "expire-old-versions"
    status = "Enabled"
    noncurrent_version_expiration { noncurrent_days = var.retention_days }
  }
}

# modules/bucket/outputs.tf
output "arn" {
  description = "Bucket ARN for downstream IAM policies"
  value       = aws_s3_bucket.this.arn
}

# envs/prod/lake.tf - consume the module three times (DRY reuse)
module "raw" {
  source         = "../../modules/bucket"
  name           = "acme-lake-raw-prod"
  retention_days = 30
}

module "curated" {
  source         = "../../modules/bucket"
  name           = "acme-lake-curated-prod"
  retention_days = 365
}

module "marts" {
  source = "../../modules/bucket"
  name   = "acme-lake-marts-prod"
}

# Wire a module output into another resource: grant read on the raw bucket
resource "aws_iam_policy" "raw_read" {
  name   = "raw-read"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["s3:GetObject"]
      Resource = "${module.raw.arn}/*"
    }]
  })
}
